e\u0433\u043e\u043d\u0435 \u0442\u043e\u0433\u043e \u0436\u0435 \u0441\u0438\u0434\u0430). \u042d\u0442\u043e \u043a\u043b\u044e\u0447\u0435\u0432\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 \u0434\u043b\u044f \u0438\u0437\u043e\u043b\u044f\u0446\u0438\u0438 \u044d\u0444\u0444\u0435\u043a\u0442\u0430: \u043e\u043d\u0430 \u043e\u0442\u0434\u0435\u043b\u044f\u0435\u0442 \u00ab\u0432\u043b\u0438\u044f\u043d\u0438\u0435 \u0441\u0430\u043c\u043e\u0433\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u0432\u0442\u043e\u0440\u0436\u0435\u043d\u0438\u044f\u00bb \u043e\u0442 \u00ab\u0432\u043b\u0438\u044f\u043d\u0438\u044f \u0431\u043e\u043b\u0435\u0435 \u0440\u0430\u043d\u043d\u0435\u0433\u043e/\u043f\u043e\u0437\u0434\u043d\u0435\u0433\u043e \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f \u0438\u0437-\u0437\u0430 \u0440\u0430\u0437\u043d\u043e\u0433\u043e \u0442\u0435\u043c\u043f\u0430 \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432\u00bb.\n\n\u0418\u0437\u043e\u043b\u044f\u0446\u0438\u044f \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0438 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441:\n- blocked vs enabled: \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u043f\u0440\u0438 \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0434\u0438\u043d\u0430\u043c\u0438\u043a\u0435 \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b.\n- enabled vs controlled: \u0432\u043a\u043b\u0430\u0434 \u00ab\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f\u00bb (score-dependent timing); \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u044d\u0442\u043e \u0441\u043c\u0435\u0448\u0435\u043d\u0438\u0435.\n- \u0412\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430 \u00d7 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 (\u0438\u0437 2\u00d73) \u2014 \u043f\u0440\u044f\u043c\u043e\u0439 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u00ab\u0432\u043b\u0438\u044f\u0435\u0442 \u043b\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u041d\u0410 \u0420\u0410\u0417\u041b\u0418\u0427\u0418\u0415 \u0432 \u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0438 \u043d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0430\u0433\u0435\u043d\u0442\u043e\u0432\u00bb.\n\n\u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430: survival duration \u2014 \u0447\u0438\u0441\u043b\u043e \u0448\u0430\u0433\u043e\u0432 \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0438 \u043e\u0442 \u0441\u0442\u0430\u0440\u0442\u0430 \u044d\u043f\u0438\u0437\u043e\u0434\u0430 \u0434\u043e \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f/\u0443\u0441\u043b\u043e\u0432\u0438\u044f \u043f\u0440\u043e\u0432\u0430\u043b\u0430, \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0441\u0432\u0435\u0440\u0445\u0443 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u043e\u043c H.\n\u0412\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435: t_trigger (\u043c\u043e\u043c\u0435\u043d\u0442 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f), \u0432\u0440\u0435\u043c\u044f \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430, \u0442\u0435\u043c\u043f \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432, \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u044f \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438, \u00ab\u043b\u0435\u0442\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c\u00bb \u0441\u043e\u0431\u044b\u0442\u0438\u044f (% \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u043e\u0439 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438).\n\n\u0410\u043d\u0430\u043b\u0438\u0437:\n- \u0414\u0432\u0443\u0445\u0444\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 (\u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0441 \u0441\u0438\u0434\u043e\u043c \u043a\u0430\u043a \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u043c \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u043c) \u043f\u043e survival-\u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438, \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f A\u00d7B, \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b \u0438 \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u044d\u0444\u0444\u0435\u043a\u0442\u0430.\n- \u0410\u043d\u0430\u043b\u0438\u0437 \u0432\u044b\u0436\u0438\u0432\u0430\u0435\u043c\u043e\u0441\u0442\u0438: Kaplan\u2013Meier + log-rank \u0438 Cox-\u043c\u043e\u0434\u0435\u043b\u044c (\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430, \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438, time-varying \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430 \u00ab\u0442\u0440\u0438\u0433\u0433\u0435\u0440 \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u043b/\u043d\u0435\u0442\u00bb, \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435); \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0438\u0441\u043a\u043e\u0432.\n- \u041e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043f\u0440\u0430\u0432\u043e\u0439 \u0446\u0435\u043d\u0437\u0443\u0440\u044b: \u043f\u0440\u043e\u0433\u043e\u043d\u044b, \u043d\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0432\u0448\u0438\u0435\u0441\u044f \u043a H, \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438.\n- \u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043f\u0440\u043e\u0433\u043e\u043d \u043f\u0440\u0438 2\u20133 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u0445 \u043f\u043e\u0440\u043e\u0433\u0430 T (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0434\u043e\u0437\u043e\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438), \u0435\u0441\u043b\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0431\u044e\u0434\u0436\u0435\u0442 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432.\n\n\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0438\u0435 \u0441\u043c\u0435\u0448\u0435\u043d\u0438\u0435:\n- Paired seeds: \u043e\u0434\u043d\u0438 \u0438 \u0442\u0435 \u0436\u0435 \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u043c\u0438\u0440\u0430 (\u043a\u0430\u0440\u0442\u0430, \u0440\u0435\u0441\u0443\u0440\u0441\u044b, \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u044f, \u0447\u0438\u0441\u043b\u043e \u0430\u0433\u0435\u043d\u0442\u043e\u0432) \u0432\u043e \u0432\u0441\u0435\u0445 6 \u044f\u0447\u0435\u0439\u043a\u0430\u0445; \u0441\u0438\u0434 \u043a\u0430\u043a \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u0444\u0430\u043a\u0442\u043e\u0440.\n- \u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u043c\u0438\u0440\u0430 \u043a\u0440\u043e\u043c\u0435 \u0444\u0430\u043a\u0442\u043e\u0440\u0430 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b.\n- \u0411\u0430\u043b\u0430\u043d\u0441 \u0442\u0435\u043c\u043f\u0430 \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432: \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u043c time-to-threshold \u043f\u043e \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c; \u043f\u0440\u0438 \u0434\u0438\u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 \u0434\u0430\u0451\u0442 \u043d\u0435\u0441\u043c\u0435\u0449\u0451\u043d\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u044f.\n- \u0420\u0435\u043f\u043b\u0438\u043a\u0438: N \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443 \u0438\u0437 \u043f\u0438\u043b\u043e\u0442\u043d\u043e\u0433\u043e power-\u0430\u043d\u0430\u043b\u0438\u0437\u0430 (\u03b1=0.05, \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c 0.80), \u0440\u0430\u043d\u0434\u043e\u043c-\u0441\u0438\u0434 \u043d\u0430 \u043a\u0430\u0436\u0434\u0443\u044e \u0440\u0435\u043f\u043b\u0438\u043a\u0443; \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u043f\u043e \u0432\u044b\u0431\u043e\u0440\u043e\u0447\u043d\u043e\u043c\u0443 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e, \u0430 \u043d\u0435 \u043f\u043e \u043e\u0434\u043d\u043e\u043c\u0443 \u043f\u0440\u043e\u0433\u043e\u043d\u0443.\n\n**2. \u0421\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u044d\u0442\u0430\u043f\u043e\u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0430**\n\u042d\u0442\u0430\u043f 0 grounding: \u043d\u0430\u0439\u0442\u0438/\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u043a\u043e\u0434 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430, \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c API, \u0442\u0440\u0438\u0433\u0433\u0435\u0440 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u00ab\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438\u00bb, \u043c\u0435\u0442\u0440\u0438\u043a\u0443 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f, \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0441\u0438\u0434\u0435; \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u044d\u0442\u043e \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 (\u0438\u043b\u0438 \u044f\u0432\u043d\u043e \u043f\u043e\u043c\u0435\u0442\u0438\u0442\u044c \u043a\u0430\u043a \u043d\u0435\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f, \u0435\u0441\u043b\u0438 \u043a\u043e\u0434 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d).\n\u042d\u0442\u0430\u043f 1 \u043f\u0438\u043b\u043e\u0442: 10\u201320 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432/\u044f\u0447\u0435\u0439\u043a\u0430 \u2192 \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u0438 survival, \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430, \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u0433\u043e\u043d\u0430 \u2192 power-\u0430\u043d\u0430\u043b\u0438\u0437 \u2192 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0435 N.\n\u042d\u0442\u0430\u043f 2 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043f\u0440\u043e\u0433\u043e\u043d 2\u00d73 \u0441 paired seeds.\n\u042d\u0442\u0430\u043f 3 \u0430\u043d\u0430\u043b\u0438\u0437 (ANOVA/\u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c + Cox + \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u043e T) \u0438 \u043e\u0442\u0447\u0451\u0442 \u0441 \u044d\u0444\u0444\u0435\u043a\u0442\u0430\u043c\u0438 \u0438 CI.\n\n**3. \u0427\u0442\u043e \u0438\u0437 \u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u043e\u0433\u043e \u043e\u043f\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b vs \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435\u043c**\n\u041e\u043f\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b: \u043d\u0438\u0447\u0435\u0433\u043e (\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432 \u043d\u0435\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0430\u043c \u0442\u0435\u0437\u0438\u0441 \u0432\u043e\u043f\u0440\u043e\u0441\u0430 \u0432 task.json).\n\u042f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435\u043c (\u0438 \u0431\u0443\u0434\u0435\u0442 \u044f\u0432\u043d\u043e \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435): \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u00ab\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438\u00bb (\u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u043b\u0438\u0434\u0435\u0440\u0441\u043a\u0438\u0445 \u0440\u043e\u043b\u0435\u0439/\u0434\u0432\u0443\u0445\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b), \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043e\u0447\u043a\u043e\u0432 \u0438 \u043f\u043e\u0440\u043e\u0433\u0430 T, \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u043f\u0440\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043f\u043e\u0442\u0435\u0440\u044f \u0434\u043e\u043b\u0438 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438), \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f/\u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f, \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043c\u0438\u0440\u0430, \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442 H, \u0447\u0438\u0441\u043b\u043e \u0440\u0435\u043f\u043b\u0438\u043a \u0438 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u043e\u0440\u043e\u0433\u0438.", "evidence": "1) `ls -la /workspace` \u0438 `find /workspace -type f`: \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u0440\u043e\u0432\u043d\u043e \u043e\u0434\u0438\u043d \u0444\u0430\u0439\u043b \u2014 task.json (482 \u0431\u0430\u0439\u0442\u0430). 2) `cat /workspace/task.json`: documents.track.md = \u00abDesign-only task; repositories and compute are not required.\u00bb \u2014 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0433\u043e track.md \u043d\u0435\u0442. 3) `find / -maxdepth 3 -name 'track.md'` \u043d\u0435 \u043d\u0430\u0448\u0451\u043b \u0444\u0430\u0439\u043b \u0432\u043e \u0432\u0441\u0435\u0439 \u0444\u0430\u0439\u043b\u043e\u0432\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u0435. 4) `python3 -V` = 3.14.4; \u0438\u043c\u043f\u043e\u0440