u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0440\u0435\u0448\u0435\u043d\u0438\u0439 (\u0447\u0430\u0441\u0442\u044c \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0433\u0440\u0443\u043f\u043f\u044b); \u043d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u2014 \u043f\u043b\u043e\u0441\u043a\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0431\u0435\u0437 \u043b\u0438\u0434\u0435\u0440\u043e\u0432; \u0442\u043e\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0434\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u0442\u044c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e API \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u043d\u0430 \u044d\u0442\u0430\u043f\u0435 grounding.", "\u0412\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u0430\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u2014 \u044d\u0442\u043e \u0434\u0438\u0441\u043a\u0440\u0435\u0442\u043d\u043e\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 (\u043d\u0430\u043f\u0440., \u0432\u0442\u043e\u0440\u0436\u0435\u043d\u0438\u0435 \u043f\u0438\u0440\u0430\u0442\u043e\u0432), \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u0435 \u043e\u0434\u0438\u043d \u0438\u043b\u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0437 \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u043d\u044b\u043c \u0441\u0447\u0451\u0442\u043e\u043c \u043f\u043e\u0440\u043e\u0433\u0430 T; \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f (\u043d\u0430\u043f\u0440., \u043f\u043e\u0442\u0435\u0440\u044f \u0434\u043e\u043b\u0438 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438) \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f