38\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0433\u043e \u043d\u0430\u0443\u0447\u043d\u043e\u0433\u043e \u0441\u0442\u0435\u043a\u0430; \u0434\u043b\u044f design-only \u044d\u0442\u0430\u043f\u0430 \u044d\u0442\u043e \u043d\u0435\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e.\n**\u0412\u044b\u0432\u043e\u0434:** \u043b\u044e\u0431\u044b\u0435 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u0438\u043a\u0438 \u043e\u0431 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0435, \u0442\u0440\u0438\u0433\u0433\u0435\u0440\u0430\u0445, \u043c\u0435\u0442\u0440\u0438\u043a\u0435 \u0438 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430\u0445 \u043c\u0438\u0440\u0430 \u043d\u0435 \u0438\u043c\u0435\u044e\u0442 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u043f\u043e\u0440\u044b \u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u044f\u0432\u043d\u043e \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (see \u00a76 \u2014 \u0432\u0441\u0435 \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u044b \u043a\u0430\u043a *assumption*). \u041f\u0435\u0440\u0432\u044b\u043c \u0448\u0430\u0433\u043e\u043c \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u044d\u0442\u0430\u043f 0 (grounding) \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e API \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u0434\u043e \u0437\u0430\u043c\u043e\u0440\u043e\u0437\u043a\u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438.\n\n---\n\n## 1. \u041f\u043e\u043b\u043d\u0430\u044f \u0441\u0445\u0435\u043c\u0430 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\n\n### 1.1 \u0424\u0430\u043a\u0442\u043e\u0440\u044b \u0438 \u0443\u0440\u043e\u0432\u043d\u0438\n**\u0424\u0430\u043a\u0442\u043e\u0440 A \u2014 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430 \u0430\u0433\u0435\u043d\u0442\u043e\u0432** (\u043c\u0435\u0436\u0434\u0443-\u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0439):\n- A_H: \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f (operationalization \u0441\u043c. \u00a73);\n- A_N: \u043d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f (\u0431\u0430\u0437\u043e\u0432\u0430\u044f \u043b\u0438\u043d\u0438\u044f, \u043f\u043b\u043e\u0441\u043a\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430).\n\n**\u0424\u0430\u043a\u0442\u043e\u0440 B \u2014 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u043e\u0439 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438** (\u0432\u043d\u0443\u0442\u0440\u0438-\u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0439 \u043f\u043e \u0441\u0438\u0434\u0443, paired):\n- B_enabled: \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u0430, \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0448\u0442\u0430\u0442\u043d\u043e \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u043d\u044b\u043c \u0441\u0447\u0451\u0442\u043e\u043c \u043f\u043e\u0440\u043e\u0433\u0430 T;\n- B_blocked: \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 (\u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f) \u2192 \u00ab\u0431\u0430\u0437\u043e\u0432\u044b\u0439 \u0443\u0440\u043e\u0432\u0435\u043d\u044c\u00bb \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0431\u0435\u0437 \u0442\u0440\u0438\u0433\u0433\u0435\u0440\u0430;\n- B_controlled: \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u0430, \u043d\u043e \u0442\u0440\u0438\u0433\u0433\u0435\u0440 \u041e\u0422\u0412\u042f\u0417\u0410\u041d \u043e\u0442 \u0441\u0447\u0451\u0442\u0430 \u2014 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f \u0432 \u043c\u043e\u043c\u0435\u043d\u0442 t*, \u0440\u0430\u0432\u043d\u044b\u0439 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f \u0432 \u043f\u0430\u0440\u043d\u043e\u043c \u043f\u0440\u043e\u0433\u043e\u043d\u0435 B_enabled \u0442\u043e\u0433\u043e \u0436\u0435 \u0441\u0438\u0434\u0430 \u0438 \u0442\u043e\u0439 \u0436\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b (paired-by-seed). \u042d\u0442\u043e \u043a\u043b\u044e\u0447\u0435\u0432\u0430\u044f \u044f\u0447\u0435\u0439\u043a\u0430 \u0434\u043b\u044f \u0438\u0437\u043e\u043b\u044f\u0446\u0438\u0438 \u044d\u0444\u0444\u0435\u043a\u0442\u0430: \u043e\u043d\u0430 \u043e\u0442\u0434\u0435\u043b\u044f\u0435\u0442 \u00ab\u0432\u043b\u0438\u044f\u043d\u0438\u0435 \u0441\u0430\u043c\u043e\u0433\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u0432\u0442\u043e\u0440\u0436\u0435\u043d\u0438\u044f\u00bb \u043e\u0442 \u00ab\u0432\u043b\u0438\u044f\u043d\u0438\u044f \u0441\u043c\u0435\u0449\u0451\u043d\u043d\u043e\u0433\u043e \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f, \u0432\u044b\u0437\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u0440\u0430\u0437\u043d\u044b\u043c \u0442\u0435\u043c\u043f\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432\u00bb.\n\n### 1.2 \u042f\u0447\u0435\u0439\u043a\u0438 \u0438 \u0447\u0438\u0441\u043b\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u0439\n6 \u044f\u0447\u0435\u0435\u043a: A \u2208 {H, N} \u00d7 B \u2208 {enabled, blocked, controlled}. \u041f\u043e\u043b\u043d\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 2\u00d73.\n\n### 1.3 Paired-seed \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u0438 \u00ab\u043f\u0430\u0440\u043d\u043e\u0441\u0442\u044c\u00bb controlled-\u044f\u0447\u0435\u0439\u043a\u0438\n1. \u0413\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u0443\u043b \u0438\u0437 R \u0431\u0430\u0437\u043e\u0432\u044b\u0445 \u0441\u0438\u0434\u043e\u0432 S = {s_1, \u2026, s_R}.\n2. \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0438\u0434\u0430 s_r \u0438 \u043a\u0430\u0436\u0434\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b A \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u044e\u0442\u0441\u044f \u0412\u0421\u0415 \u0442\u0440\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f B \u0441 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u043c\u0438 \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u043c\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c\u0438 \u043c\u0438\u0440\u0430 (\u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435 \u043a\u0430\u0440\u0442\u0430, \u0440\u0435\u0441\u0443\u0440\u0441\u044b, \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u0430\u044f \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u044f, \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u0437\u0438\u0446\u0438\u0438, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u043c\u0438\u0440\u0430, \u043e\u0442\u043b\u0438\u0447\u043d\u0430\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u043c A).\n3. \u0414\u043b\u044f \u044f\u0447\u0435\u0439\u043a\u0438 (A, controlled): \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0433\u043e\u043d (A, enabled, s_r), \u0438\u0437 \u043d\u0435\u0433\u043e \u0441\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f t_trigger*(A, s_r); \u0437\u0430\u0442\u0435\u043c \u0442\u043e\u0442 \u0436\u0435 \u0441\u0438\u0434 s_r \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0441 \u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u043c \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u0432 t* = t_trigger*(A, s_r). \u041f\u0430\u0440\u044b \u00abenabled \u2194 controlled\u00bb \u0438\u043c\u0435\u044e\u0442 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 \u0438 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0439 \u043c\u0438\u0440: \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0442\u043e\u043c, \u0447\u0442\u043e \u0432 controlled \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u041d\u0415 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u043f\u043e\u0440\u043e\u0433\u0430 \u0441\u0447\u0451\u0442\u0430 \u043a \u044d\u0442\u043e\u043c\u0443 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 (\u0442.\u0435. \u043e\u0442 \u00ab\u0443\u0441\u043f\u0435\u043b \u043b\u0438 \u0430\u0433\u0435\u043d\u0442 \u043d\u0430\u0431\u0440\u0430\u0442\u044c \u043e\u0447\u043a\u0438\u00bb).\n4. \u0421\u0438\u0434 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u044e\u0449\u0438\u0439 (\u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439) \u0444\u0430\u043a\u0442\u043e\u0440 \u0432\u043e \u0432\u0441\u0435\u0445 \u043c\u043e\u0434\u0435\u043b\u044f\u0445.\n\n### 1.4 \u0420\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f\n- \u041a\u0430\u0436\u0434\u044b\u0439 \u0441\u0438\u0434 s_r \u2014 \u043e\u0434\u043d\u0430 \u0440\u0435\u043f\u043b\u0438\u043a\u0430 \u00ab\u0442\u0440\u043e\u0439\u043a\u0438\u00bb (enabled/blocked/controlled) \u0434\u043b\u044f \u0434\u0430\u043d\u043d\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b.\n- \u041e\u0431\u0449\u0435\u0435 \u0447\u0438\u0441\u043b\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432: 2 (\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b) \u00d7 R (\u0441\u0438\u0434\u043e\u0432) \u00d7 3 (\u0443\u0441\u043b\u043e\u0432\u0438\u044f B). R \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f power-\u0430\u043d\u0430\u043b\u0438\u0437\u043e\u043c (\u00a77); \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 R \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440, \u0430 \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u0430\u044f \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0430.\n- \u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0437\u0435\u0440\u0432: \u00b110% \u0437\u0430\u043f\u0430\u0441\u043d\u044b\u0445 \u0441\u0438\u0434\u043e\u0432 \u043d\u0430 \u0441\u043b\u0443\u0447\u0430\u0439 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0441\u0431\u043e\u0435\u0432/\u0432\u044b\u0431\u0440\u043e\u0441\u043e\u0432, \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u043c\u044b\u0445 \u0432 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 \u0431\u0435\u0437 \u044f\u0432\u043d\u043e\u0433\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f (\u043f\u0440\u0430\u0432\u0438\u043b\u043e: \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u044b \u0441 \u0437\u0430\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u0441\u0431\u043e\u0435\u043c \u2014 \u043f\u0430\u0434\u0435\u043d\u0438\u0435\u043c/\u0430\u0431\u043e\u0440\u0442\u043e\u043c \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430; \u0432\u044b\u0431\u0440\u043e\u0441\u044b \u043f\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c \u041d\u0415 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f, \u0430 \u0430\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0435\u0441\u0442\u044c).\n\n---\n\n## 2. \u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f (\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f)\n\n### 2.1 \u041c\u0435\u0442\u0430-\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f\n\u0412\u0441\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438\u0437\u043c\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u0432 \u00ab\u0448\u0430\u0433\u0430\u0445 \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0438\u00bb (tick/time-step) \u043e\u0442 \u0441\u0442\u0430\u0440\u0442\u0430 \u044d\u043f\u0438\u0437\u043e\u0434\u0430. \u042d\u043f\u0438\u0437\u043e\u0434 \u2014 \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u0433\u043e\u043d (seed, \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430, \u0443\u0441\u043b\u043e\u0432\u0438\u0435 B).\n\n### 2.2 \u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430: survival duration\n- **\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435:** D = \u0447\u0438\u0441\u043b\u043e \u0448\u0430\u0433\u043e\u0432 \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0438 \u043e\u0442 \u0441\u0442\u0430\u0440\u0442\u0430 \u044d\u043f\u0438\u0437\u043e\u0434\u0430 \u0434\u043e \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f/\u043f\u0440\u043e\u0432\u0430\u043b\u0430 (\u0441\u043c. 2.6), \u043b\u0438\u0431\u043e \u0434\u043e \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u0430 H, \u0435\u0441\u043b\u0438 \u044d\u043f\u0438\u0437\u043e\u0434 \u043d\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043b\u0441\u044f \u043a H.\n- **\u0426\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435:** \u0435\u0441\u043b\u0438 \u044d\u043f\u0438\u0437\u043e\u0434 \u0432\u0441\u0451 \u0435\u0449\u0451 \u00ab\u0436\u0438\u0432\u00bb \u0432 \u043c\u043e\u043c\u0435\u043d\u0442 H, D = H \u0438 \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0435 \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043f\u0440\u0430\u0432\u043e-\u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 (censored = 1). H \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0434\u0438\u0437\u0430\u0439\u043d\u0430 (assumption, \u00a76), \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u043c\u044b\u0439 \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435 \u0442\u0430\u043a, \u0447\u0442\u043e\u0431\u044b \u0431\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u043b\u043e\u0441\u044c \u0434\u043e H.\n- \u0412\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0430\u0433\u0440\u0435\u0433\u0430\u0442\u044b: \u043c\u0435\u0434\u0438\u0430\u043d\u0430 \u0438 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 D \u043f\u043e \u044f\u0447\u0435\u0439\u043a\u0435, KM-\u043a\u0440\u0438\u0432\u0430\u044f, \u0434\u043e\u043b\u044f \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445.\n\n### 2.3 t_trigger (\u043c\u043e\u043c\u0435\u043d\u0442 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438)\n- **\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435:** \u0448\u0430\u0433 \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0438, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 (\u0432\u0442\u043e\u0440\u0436\u0435\u043d\u0438\u0435). \u0414\u043b\u044f B_enabled \u2014 \u043c\u043e\u043c\u0435\u043d\u0442 \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u044f \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u043d\u044b\u043c \u0441\u0447\u0451\u0442\u043e\u043c \u043f\u043e\u0440\u043e\u0433\u0430 T; \u0434\u043b\u044f B_controlled \u2014 \u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 t* (\u0440\u0430\u0432\u043d\u044b\u0439 \u043f\u0430\u0440\u043d\u043e\u043c\u0443 t_trigger* \u0438\u0437 enabled \u0442\u043e\u0433\u043e \u0436\u0435 \u0441\u0438\u0434\u0430 \u0438 \u0442\u043e\u0439 \u0436\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b); \u0434\u043b\u044f B_blocked \u2014 \u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d (\u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u043d\u0435 \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0434\u0438\u0442).\n- \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f: (\u0430) \u043a\u0430\u043a time-varying \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430 \u00ab\u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u043b\u043e\u00bb \u0432 Cox-\u043c\u043e\u0434\u0435\u043b\u0438; (\u0431) \u0434\u043b\u044f \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u0431\u0430\u043b\u0430\u043d\u0441\u0430 \u0442\u0435\u043c\u043f\u0430 \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432; (\u0432) \u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438 \u043f\u0430\u0440\u043d\u043e\u0441\u0442\u0438 controlled (t_trigger_controlled \u2261 t_trigger_enabled \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u043f\u0430\u0440\u044b).\n\n### 2.4 time-to-threshold (\u0432\u0440\u0435\u043c\u044f \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430)\n- **\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435:** \u0448\u0430\u0433, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u043d\u044b\u0439 \u0441\u0447\u0451\u0442 \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u0432\u043f\u0435\u0440\u0432\u044b\u0435 \u0434\u043e\u0441\u0442\u0438\u0433\u0430\u0435\u0442 T. \u0420\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439; \u0432 B_blocked/controlled \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u00ab\u043a\u0430\u043a \u0435\u0441\u043b\u0438 \u0431\u044b \u043f\u043e\u0440\u043e\u0433 \u0431\u044b\u043b\u00bb, \u0442.\u0435. \u043f\u043e \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 \u0441\u0447\u0451\u0442\u0443 \u2014 \u044d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0442\u044c \u0442\u0435\u043c\u043f \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u043e\u0442 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438.\n- \u041d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435: \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0430 \u0441\u043c\u0435\u0448\u0435\u043d\u0438\u044f \u00ab\u0440\u0430\u0437\u043d\u044b\u0439 \u0442\u0435\u043c\u043f \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432 \u2192 \u0440\u0430\u0437\u043d\u044b\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f\u00bb; \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0439 (\u00a74) \u0438 \u043a\u0430\u043a \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.\n\n### 2.5 \u041b\u0435\u0442\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0441\u043e\u0431\u044b\u0442\u0438\u044f (severity)\n- **\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435:** \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438/\u0437\u0434\u043e\u0440\u043e\u0432\u044c\u044f, \u0432\u044b\u0437\u0432\u0430\u043d\u043d\u043e\u0435 \u043e\u0434\u043d\u0438\u043c \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435\u043c: L = (pop(t*) \u2212 pop(t*+1)) / pop(t*), \u0433\u0434\u0435 pop \u2014 \u0440\u0430\u0437\u043c\u0435\u0440 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438 (\u0438\u043b\u0438 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e\u0435 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435/\u044d\u043d\u0435\u0440\u0433\u0438\u044f \u0430\u0433\u0435\u043d\u0442\u043e\u0432, \u043f\u043e \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430) \u043d\u0435\u043f\u043e\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u0434\u043e \u0438 \u043f\u043e\u0441\u043b\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f.\n- \u0414\u043b\u044f \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0439 \u2014 \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c L_j, j = 1..k.\n- \u041d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435: \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u043e\u0433\u043e \u044d\u0444\u0444\u0435\u043a\u0442\u0430 (\u0441\u0438\u043b\u044c\u043d\u043e\u0435 vs \u0441\u043b\u0430\u0431\u043e\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435) \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e controlled-\u044f\u0447\u0435\u0439\u043a\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u043e\u0440\u043e\u0436\u0434\u0430\u0435\u0442 \u0442\u043e \u0436\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u0447\u0442\u043e \u0438 enabled (\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u043b\u0435\u0442\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0438 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u043c \u043c\u0438\u0440\u0435).\n\n### 2.6 \u0422\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u044f \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f/\u043f\u0440\u043e\u0432\u0430\u043b\u0430\n- **\u0422\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u044f:** \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c pop(t) \u0434\u043b\u044f t = 0..min(D,H). \u0421\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0434\u043b\u044f \u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0444\u043e\u0440\u043c\u044b \u043a\u0440\u0438\u0432\u043e\u0439.\n- **\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f (\u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u043f\u0440\u043e\u0432\u0430\u043b\u0430):** pop(t) \u2264 1 (\u0438\u043b\u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u0430\u0435\u0442 \u0437\u0430\u0434\u0430\u043d\u043d\u043e\u0433\u043e \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442), \u0442.\u0435. \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u0435 \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f, \u043a\u043e\u0433\u0434\u0430 \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u043d\u0435 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f. \u0422\u043e\u0447\u043d\u043e\u0435 \u043f\u043e\u0440\u043e\u0433\u043e\u0432\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 (1 vs 0 vs \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0439 \u043c\u0438\u043d\u0438\u043c\u0443\u043c) \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u0430\u043f\u0435 grounding \u043f\u043e \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u0435 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 (assumption, \u00a76, P8), \u0438 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u041e\u0414\u0418\u041d\u0410\u041a\u041e\u0412\u041e \u043a\u043e \u0432\u0441\u0435\u043c \u044f\u0447\u0435\u0439\u043a\u0430\u043c.\n\n### 2.7 \u0421\u0432\u043e\u0434\u043d\u0430\u044f \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0434\u0430\u043d\u043d\u044b\u0445\n\u041d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f: (seed, A, B, D, censored, t_trigger, time-to-threshold, L, pop-\u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u044f, T, H, \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u043c\u0438\u0440\u0430, \u0432\u0435\u0440\u0441\u0438\u044f \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430/\u043a\u043e\u0434\u0430).\n\n---\n\n## 3. \u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u00ab\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438\u00bb \u0438 \u043d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u043b\u0438\u043d\u0438\u0438\n\n**Assumption (\u043d\u0435\u0442 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u043f\u043e\u0440\u044b) \u2014 P1 (\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438).**\n- **\u0418\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f (A_H):** \u0430\u0433\u0435\u043d\u0442\u044b \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u043e\u0432\u0430\u043d\u044b \u0432 \u0434\u0432\u0443\u0445\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u0443\u044e (\u0432 \u043e\u0431\u0449\u0435\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u043c\u043d\u043e\u0433\u043e\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u0443\u044e) \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443: \u0432\u044b\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u00ab\u043b\u0438\u0434\u0435\u0440\u043e\u0432\u00bb (\u0432\u0435\u043b\u0438\u0447\u0438\u043d\u043e\u0439, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, 20% \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438), \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0433\u0440\u0443\u043f\u043f\u043e\u0432\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f (\u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432, \u0432\u044b\u0431\u043e\u0440 \u0446\u0435\u043b\u0435\u0439, \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0446\u0438\u044f \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439), \u0432\u043b\u0438\u044f\u044e\u0449\u0438\u0435 \u043d\u0430 \u043f\u043e\u0434\u0447\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0433\u0440\u0443\u043f\u043f\u044b; \u043f\u043e\u0434\u0447\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0441\u043b\u0435\u0434\u0443\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043c \u043b\u0438\u0434\u0435\u0440\u043e\u0432.\n- **\u041d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f (A_N):** \u043f\u043b\u043e\u0441\u043a\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430: \u0432\u0441\u0435 \u0430\u0433\u0435\u043d\u0442\u044b \u043e\u0434\u043d\u043e\u0440\u043e\u0434\u043d\u043e \u0430\u0432\u0442\u043e\u043d\u043e\u043c\u043d\u044b, \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u043f\u043e \u043e\u0434\u043d\u043e\u043c\u0443 \u0438 \u0442\u043e\u043c\u0443 \u0436\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0443, \u043b\u0438\u0434\u0435\u0440\u0441\u043a\u0438\u0435 \u0440\u043e\u043b\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442; \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0438 \u00ab\u0442\u0435\u043b\u043e\u00bb \u043f\u0440\u0430\u0432\u0438\u043b \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u044f \u0440\u0435\u0448\u0435\u043d\u0438\u0439 \u0443 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0445 \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435.\n- **\u0421\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u043e\u0441\u0442\u044c:** \u0447\u0442\u043e\u0431\u044b \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u043b\u0438\u0441\u044c \u0422\u041e\u041b\u042c\u041a\u041e \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0441\u0432\u044f\u0437\u0438, \u0430 \u043d\u0435 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e/\u0442\u0438\u043f \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0438\u0445 \u043f\u0440\u0438\u043c\u0438\u0442\u0438\u0432\u043e\u0432: \u0430\u0433\u0435\u043d\u0442\u044b \u043e\u0431\u043e\u0438\u0445 \u0442\u0438\u043f\u043e\u0432 \u0438\u043c\u0435\u044e\u0442 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0443\u044e \u00ab\u0440\u0430\u0434\u0438\u0443\u0441/\u0437\u0440\u0435\u043d\u0438\u0435\u00bb, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u0438 \u0438 \u0442.\u0434. \u0412 A_H \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0445 \u0441\u0438\u0433\u043d\u0430\u043b\u043e\u0432 \u043e\u0442 \u043b\u0438\u0434\u0435\u0440\u0430 \u043a \u0433\u0440\u0443\u043f\u043f\u0435; \u0432 A_N \u0442\u0430\u043a\u043e\u0433\u043e \u043a\u0430\u043d\u0430\u043b\u0430 \u043d\u0435\u0442.\n- \u0422\u043e\u0447\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f (\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043b\u0438 \u043b\u0438\u0434\u0435\u0440\u044b \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u0438\u0437\u0431\u0438\u0440\u0430\u0435\u043c\u044b\u043c\u0438, \u0440\u0430\u0437\u043c\u0435\u0440 \u0433\u0440\u0443\u043f\u043f, \u0434\u043e\u043b\u044f \u043b\u0438\u0434\u0435\u0440\u043e\u0432) \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u0430\u043f\u0435 grounding \u043f\u043e \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u043c\u0443 API \u0438 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0434\u0438\u0437\u0430\u0439\u043d \u043a\u0430\u043a \u044f\u0432\u043d\u044b\u0439 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440; \u0435\u0441\u043b\u0438 API \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u2014 \u043a\u0430\u043a assumption P1 \u0441 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u0434\u043e\u043b\u044f \u043b\u0438\u0434\u0435\u0440\u043e\u0432 20%, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0440\u043e\u043b\u0438 \u043d\u0430 \u0432\u0435\u0441\u044c \u044d\u043f\u0438\u0437\u043e\u0434).\n\n**\u041d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0431\u0430\u0437\u043e\u0432\u0430\u044f \u043b\u0438\u043d\u0438\u044f:** A_N \u043f\u0440\u0438 \u0442\u0435\u0445 \u0436\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430\u0445 \u043c\u0438\u0440\u0430, \u0447\u0442\u043e \u0438 A_H (\u043e\u0434\u043d\u0430 \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u0430\u044f \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u044f, \u0442\u0435 \u0436\u0435 \u0440\u0435\u0441\u0443\u0440\u0441\u044b), \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0435\u0437 \u043b\u0438\u0434\u0435\u0440\u0441\u043a\u0438\u0445 \u0440\u043e\u043b\u0435\u0439. \u041e\u043d\u0430 \u0436\u0435 \u2014 \u00ab\u0431\u0430\u0437\u0430\u00bb \u0434\u043b\u044f \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u0432\u043b\u0438\u044f\u043d\u0438\u044f \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438 \u043a\u0430\u043a \u0442\u0430\u043a\u043e\u0432\u043e\u0439, \u0430 \u043d\u0435 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u043c\u0438\u0440\u0430.\n\n---\n\n## 4. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0438\u0435 \u0441\u043c\u0435\u0448\u0435\u043d\u0438\u0435\n\n### 4.1 \u0411\u0430\u043b\u0430\u043d\u0441 \u0442\u0435\u043c\u043f\u0430 \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432 (\u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u043a\u043e\u043d\u0444\u0430\u043d\u0434)\n\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u0430: \u0435\u0441\u043b\u0438 A_H \u043d\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u043e\u0447\u043a\u0438 \u0431\u044b\u0441\u0442\u0440\u0435\u0435, \u0432 B_enabled \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0440\u0430\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0443 A_N \u2014 \u044d\u0444\u0444\u0435\u043a\u0442 \u00ab\u0440\u0430\u043d\u044c\u0448\u0435 \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u043b\u043e\u00bb \u0441\u043c\u0435\u0448\u0430\u043d \u0441 \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u043c \u00ab\u0441\u0430\u043c\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u0435\u00bb.\n\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0442\u0440\u043e\u0439\u043d\u043e\u0439:\n1. **\u042f\u0447\u0435\u0439\u043a\u0430 B_controlled** (\u043f\u0430\u0440\u043d\u0430\u044f \u043f\u043e \u0441\u0438\u0434\u0443 \u043a B_enabled): \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0432 t*, \u0442\u0430\u043a \u0447\u0442\u043e \u043c\u043e\u043c\u0435\u043d\u0442 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f \u0443 controlled \u0418\u0414\u0415\u041d\u0422\u0418\u0427\u0415\u041d \u043f\u0430\u0440\u043d\u043e\u043c\u0443 enabled \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u00abenabled vs controlled\u00bb \u0443\u0431\u0438\u0440\u0430\u0435\u0442 timing-\u043a\u0430\u043d\u0430\u043b; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u00abcontrolled vs blocked\u00bb \u0432\u044b\u0434\u0435\u043b\u044f\u0435\u0442 \u0447\u0438\u0441\u0442\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u044f.\n2. **\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0430 time-to-threshold** (\u00a72.4): \u043f\u043e \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 \u0441\u0447\u0451\u0442\u0443 \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u043c, \u043e\u0442\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u043b\u0438 \u0442\u0435\u043c\u043f \u043d\u0430\u0431\u043e\u0440\u0430 \u043e\u0447\u043a\u043e\u0432 \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c\u0438; \u0434\u043e\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u044f\u0432\u043d\u043e.\n3. **\u041a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430 \u0432 \u0430\u043d\u0430\u043b\u0438\u0437\u0435:** time-to-threshold \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430/\u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u0444\u0430\u043a\u0442\u043e\u0440 \u0432 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u043e\u0434\u0435\u043b\u0438.\n\n### 4.2 \u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u043c\u0438\u0440\u0430 \u0438 \u0440\u0430\u0437\u043c\u0435\u0440 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438\n- \u041a\u0430\u0440\u0442\u0430 (\u0440\u0430\u0437\u043c\u0435\u0440, \u0440\u0435\u043b\u044c\u0435\u0444), \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432, \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432, \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u0430\u044f \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438, \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442 H, \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438 \u2014 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b \u0432\u043e \u0432\u0441\u0435\u0445 6 \u044f\u0447\u0435\u0439\u043a\u0430\u0445 \u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u043a\u0430\u043a \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b (P4, P5, P6 \u2014 assumptions).\n- \u0415\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u043e\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 A_H \u0438 A_N \u2014 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0430\u0433\u0435\u043d\u0442\u043e\u0432 (\u00a73); \u043c\u0435\u0436\u0434\u0443 B-\u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c\u0438 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u0438 (\u0432 controlled) \u043c\u043e\u043c\u0435\u043d\u0442 \u0435\u0451 \u0437\u0430\u043f\u0443\u0441\u043a\u0430.\n\n### 4.3 \u0421\u0438\u0434-\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435)\n- \u0413\u0438\u043f\u043e\u0442\u0435\u0437\u0430 \u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438: \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0441\u0438\u0434\u0435 \u0438 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430\u0445 \u043f\u0440\u043e\u0433\u043e\u043d \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c (\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d) \u043b\u0438\u0431\u043e \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u0435\u043d.\n- \u041f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435: \u043a\u0430\u0436\u0434\u044b\u0439 \u0438\u0437 K \u043f\u0438\u043b\u043e\u0442\u043d\u044b\u0445 \u0441\u0438\u0434\u043e\u0432 \u043f\u0440\u043e\u0433\u043e\u043d\u044f\u0435\u0442\u0441\u044f m=3 \u0440\u0430\u0437\u0430 \u0432 \u043e\u0434\u043d\u043e\u0439 \u0438 \u0442\u043e\u0439 \u0436\u0435 \u044f\u0447\u0435\u0439\u043a\u0435 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, (A_N, blocked)); \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f D, pop-\u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u0438 \u0438 \u043c\u043e\u043c\u0435\u043d\u0442\u044b \u043b\u044e\u0431\u044b\u0445 \u0441\u043e\u0431\u044b\u0442\u0438\u0439.\n  - \u0415\u0441\u043b\u0438 \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0441\u0438\u0434\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b \u2192 \u0441\u0438\u0434 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u044e (\u00ab\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u00bb): \u0442\u043e\u0433\u0434\u0430 \u0441\u0438\u0434 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u0438 \u043c\u0435\u0436\u0434\u0443 \u0441\u0438\u0434\u0430\u043c\u0438, \u0438 paired-\u0434\u0438\u0437\u0430\u0439\u043d \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u044e \u043c\u0438\u0440\u0430; \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f = \u0447\u0438\u0441\u043b\u043e \u0441\u0438\u0434\u043e\u0432.\n  - \u0415\u0441\u043b\u0438 \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0441\u0438\u0434\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u0442\u0441\u044f \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044f\u044f \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c (\u0440\u0430\u0437\u0431\u0440\u043e\u0441 \u043c\u0435\u0436\u0434\u0443 \u043f\u043e\u0432\u0442\u043e\u0440\u0430\u043c\u0438 \u0441\u0438\u0434\u0430) \u2192 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432\u043d\u0443\u0442\u0440\u0438-\u0441\u0438\u0434\u043e\u0432\u0430\u044f \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u044f \u0438 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0432 power-\u0430\u043d\u0430\u043b\u0438\u0437; \u043f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u043a\u0430\u0436\u0434\u044b\u0439 (seed) \u2192 (seed, \u043f\u043e\u0432\u0442\u043e\u0440\u0430) \u0441 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044c\u044e \u2265 2\u20133.\n- \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 (\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u0438\u043b\u0438 \u0435\u0433\u043e \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435).\n\n### 4.4 \u041f\u0440\u043e\u0447\u0438\u0435 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\n- \u0414\u043e\u043b\u044f \u043b\u0438\u0434\u0435\u0440\u043e\u0432 \u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u043f\u0435\u0440\u0435\u0438\u0437\u0431\u0440\u0430\u043d\u0438\u044f (\u0432 grounding/\u043f\u0438\u043b\u043e\u0442\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0438 \u043d\u0435 \u0432\u0430\u0440\u044c\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432\u043d\u0443\u0442\u0440\u0438 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430).\n- \u0412\u0435\u0440\u0441\u0438\u044f \u043a\u043e\u0434\u0430 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u0438 \u0432\u0441\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043b\u043e\u0433\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u043a\u0430\u0436\u0434\u044b\u043c \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u043c.\n- \u041e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f \u0438 \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445.\n- \u041f\u0440\u0435\u0434\u043e\u0442\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u00ab\u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0442\u0435\u043b\u044f\u00bb/\u0432\u043c\u0435\u0448\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430: \u043d\u0438 \u043e\u0434\u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0430 \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 \u0440\u0443\u0447\u043d\u043e\u0439 \u043f\u043e\u0434\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043f\u0440\u043e\u0433\u043e\u043d\u0430.\n\n---\n\n## 5. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0441 \u044f\u0432\u043d\u044b\u043c \u043e\u0442\u0432\u0435\u0442\u043e\u043c \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\n\n### 5.1 \u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430\n1. **\u0422\u0430\u0431\u043b\u0438\u0446\u0430 \u0441\u0432\u043e\u0434\u043e\u043a \u043f\u043e \u044f\u0447\u0435\u0439\u043a\u0430\u043c:** \u043c\u0435\u0434\u0438\u0430\u043d\u0430/\u0441\u0440\u0435\u0434\u043d\u0435\u0435 D, \u0434\u043e\u043b\u044f \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445, t_trigger, time-to-threshold, L \u2014 \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u0439 \u0438\u0437 6 \u044f\u0447\u0435\u0435\u043a, \u0441 bootstrap-\u0414\u0418.\n2. **KM-\u043a\u0440\u0438\u0432\u044b\u0435 \u0438 log-rank:** 6 \u043a\u0440\u0438\u0432\u044b\u0445; \u043f\u043e\u043f\u0430\u0440\u043d\u044b\u0435 log-rank \u0442\u0435\u0441\u0442\u044b \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u0430\u0436\u0434\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b (blocked vs enabled vs controlled) \u0438 \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c\u0438 \u0432 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0445 B-\u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445; \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0438 \u043d\u0430 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, Holm).\n3. **Cox-\u043c\u043e\u0434\u0435\u043b\u044c (\u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f):** h(t) = h_0(t) \u00d7 exp(\u03b2_A\u00b7A + \u03b2_B2\u00b7[B=controlled] + \u03b2_B3\u00b7[B=enabled] + \u03b2_A\u00d7B2\u00b7A:[B=controlled] + \u03b2_A\u00d7B3\u00b7A:[B=enabled] + \u03b3(t)\u00b7X_trigger(t)), \u0433\u0434\u0435 X_trigger(t) \u2014 time-varying \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430 0/1 \u00ab\u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u0443\u0436\u0435 \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u043b\u043e \u043a \u043c\u043e\u043c\u0435\u043d\u0442\u0443 t\u00bb, \u0438 \u0432\u043a\u043b\u044e\u0447\u0451\u043d \u03b3(t) (\u0441\u0442\u0443\u043f\u0435\u043d\u0447\u0430\u0442\u0430\u044f \u0438\u043b\u0438 \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043f\u043e\u0441\u043b\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f). \u0421\u0438\u0434 \u2014 \u043a\u043b\u0430\u0441\u0442\u0435\u0440 (robust sandwich covariance) \u043b\u0438\u0431\u043e \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e \u0441\u0438\u0434\u0443, \u0435\u0441\u043b\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0442 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u044b. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0440\u0438\u0441\u043a\u043e\u0432 (Schoenfeld-\u043e\u0441\u0442\u0430\u0442\u043a\u0438, \u0438\u043b\u0438 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442 \u0441 log(t)); \u043f\u0440\u0438 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0438 \u2014 \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0438\u043b\u0438 time-dependent-\u0430\u0434\u0430\u043f\u0442\u0430\u0446\u0438\u044f.\n\n### 5.2 \u042f\u0432\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u0447\u0435\u0440\u0435\u0437 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 A\u00d7B\n- **\u041a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 \u00ab\u044d\u0444\u0444\u0435\u043a\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u0434\u043b\u044f \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b A\u00bb:** \u0394_A = D(A, enabled) \u2212 D(A, blocked) (\u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u043f\u0440\u0438 \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u043c \u0442\u0430\u0439\u043c\u0438\u043d\u0433\u0435) \u0438 \u0394_A^ctrl = D(A, controlled) \u2212 D(A, blocked) (\u0447\u0438\u0441\u0442\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u044f, \u0431\u0435\u0437 timing-\u043a\u0430\u043d\u0430\u043b\u0430).\n- **\u041a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 \u00ab\u0432\u043b\u0438\u044f\u0435\u0442 \u043b\u0438 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u043d\u0430 \u0420\u0410\u0417\u041b\u0418\u0427\u0418\u0415 \u0432 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u0438 \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0438\u0445 vs \u043d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0438\u0445\u00bb \u2014 \u044d\u0442\u043e \u0412\u0417\u0410\u0418\u041c\u041e\u0414\u0415\u0419\u0421\u0422\u0412\u0418\u0415 A\u00d7B:**\n  - \u041d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u0442.\u043d. interaction contrast \u00ab\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430 \u00d7 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430\u00bb: \u03b8 = (D(A_H, enabled) \u2212 D(A_H, blocked)) \u2212 (D(A_N, enabled) \u2212 D(A_N, blocked)) \u2014 \u00ab\u0438\u0437\u043c\u0435\u043d\u044f\u0435\u0442 \u043b\u0438 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0432 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u0438 H vs N\u00bb; \u0438 \u0435\u0433\u043e \u00ab\u0447\u0438\u0441\u0442\u0430\u044f\u00bb \u0432\u0435\u0440\u0441\u0438\u044f \u03b8_ctrl = (D(A_H, controlled) \u2212 D(A_H, blocked)) \u2212 (D(A_N, controlled) \u2212 D(A_N, blocked)) \u2014 \u0442\u043e \u0436\u0435 \u0434\u043b\u044f \u0447\u0438\u0441\u0442\u043e\u0433\u043e \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0441\u043e\u0431\u044b\u0442\u0438\u044f.\n  - \u0412 Cox-\u0442\u0435\u0440\u043c\u0438\u043d\u0430\u0445: \u0442\u0435\u0441\u0442 \u03b2_A\u00d7B2 = 0 \u0438 \u03b2_A\u00d7B3 = 0 (\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f), LR/LRT-\u0442\u0435\u0441\u0442 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043c\u043e\u0434\u0435\u043b\u0438 \u0441 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c \u043f\u0440\u043e\u0442\u0438\u0432 \u043c\u043e\u0434\u0435\u043b\u0438 \u0431\u0435\u0437 \u043d\u0435\u0433\u043e.\n  - \u0418\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430: \u0435\u0441\u043b\u0438 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u0438 \u03b8_ctrl \u2260 0 \u2192 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u0418\u0417\u041c\u0415\u041d\u042f\u0415\u0422 \u0441\u043e\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0435\u0439 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f H vs N (\u0442.\u0435. \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u043f\u043e-\u0440\u0430\u0437\u043d\u043e\u043c\u0443 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0434\u0432\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b); \u0435\u0441\u043b\u0438 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043d\u0435\u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043f\u0440\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u043c \u0433\u043b\u0430\u0432\u043d\u043e\u043c \u044d\u0444\u0444\u0435\u043a\u0442\u0435 B \u2192 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u043e\u0431\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e (\u0441\u0434\u0432\u0438\u0433\u043e\u043c), \u043d\u0435 \u043c\u0435\u043d\u044f\u044f \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435; \u0435\u0441\u043b\u0438 \u0438 \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u043d\u0435\u0437\u043d\u0430\u0447\u0438\u043c \u2192 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u043d\u0435 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u0435 \u043d\u0438 \u0432 \u043e\u0434\u043d\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0435.\n- **\u0414\u0435\u0442\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u00ab\u043e\u0442\u043a\u0443\u0434\u0430 \u044d\u0444\u0444\u0435\u043a\u0442\u00bb (\u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u043e\u0434\u0435\u043b\u0438):**\n  - blocked vs enabled (\u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0442\u0430\u0439\u043c\u0438\u043d\u0433) = \u0441\u043e\u0431\u044b\u0442\u0438\u0435 + timing-\u0441\u0434\u0432\u0438\u0433;\n  - blocked vs controlled = \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u0435;\n  - enabled vs controlled (\u0432\u043d\u0443\u0442\u0440\u0438 \u043f\u0430\u0440\u044b) = \u0442\u043e\u043b\u044c\u043a\u043e timing-\u0441\u0434\u0432\u0438\u0433.\n- **\u0421\u043e\u043f\u0440\u043e\u0432\u043e\u0436\u0434\u0430\u044e\u0449\u0438\u0435 \u043c\u043e\u0434\u0435\u043b\u0438:**\n  - time-to-threshold \u0438 t_trigger \u043a\u0430\u043a \u043e\u0442\u043a\u043b\u0438\u043a\u0438 (ANOVA/\u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0441 \u0441\u0438\u0434\u043e\u043c) \u2014 \u0434\u043b\u044f \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0438 \u0431\u0430\u043b\u0430\u043d\u0441\u0430 \u0442\u0435\u043c\u043f\u0430 (\u00a74.1);\n  - \u043b\u0435\u0442\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c L \u0438 \u0442\u0440\u0430\u0435\u043a\u0442\u043e\u0440\u0438\u044f pop(t) \u2014 \u0434\u043b\u044f \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438 (\u0431\u044b\u043b\u043e \u043b\u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u00ab\u0441\u0438\u043b\u044c\u043d\u044b\u043c\u00bb, \u043a\u0430\u043a \u0444\u043e\u0440\u043c\u0430 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 t*).\n- **\u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c:** \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u0438 T_low \u0438 T_high (\u0434\u043e\u0437\u043e\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c: \u0447\u0435\u043c \u0440\u0430\u043d\u044c\u0448\u0435/\u043f\u043e\u0437\u0436\u0435 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0436\u0438\u0437\u043d\u0438 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u0435, \u0442\u0435\u043c \u0441\u0438\u043b\u044c\u043d\u0435\u0435/\u0441\u043b\u0430\u0431\u0435\u0435 \u044d\u0444\u0444\u0435\u043a\u0442?) \u0438, \u043f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438, \u043f\u0440\u0438 2 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0430\u0445 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438 (\u0434\u043e\u043b\u044f \u043b\u0438\u0434\u0435\u0440\u043e\u0432 10% vs 30%), \u0435\u0441\u043b\u0438 \u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0431\u044e\u0434\u0436\u0435\u0442.\n\n### 5.3 \u041e\u0442\u0447\u0451\u0442 \u0438 \u0440\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430\n- \u0414\u043e\u043a\u043b\u0430\u0434\u044b: \u0442\u043e\u0447\u0435\u0447\u043d\u044b\u0435 \u043e\u0446\u0435\u043d\u043a\u0438 \u0438 95% \u0414\u0418 \u0434\u043b\u044f \u03b8 \u0438 \u03b8_ctrl, HR \u0434\u043b\u044f A, B-\u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0438 \u0438\u0445 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f, \u043b\u043e\u0433-\u0440\u0430\u043d\u043a p-\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f (\u0441 \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430\u043c\u0438), \u0434\u043e\u043b\u044f \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445, \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0430 PH, \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0441\u0438\u0434-\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c\u0430.\n- \u042d\u0444\u0444\u0435\u043a\u0442 \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c \u043c\u0435\u0434\u0438\u0430\u043d/\u0441\u0440\u0435\u0434\u043d\u0438\u0445 D \u0441 \u0414\u0418 (bootstrap, \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043e \u0441\u0438\u0434\u0443) \u0438 \u043a\u0430\u043a HR \u0441 \u0414\u0418 \u2014 \u043e\u0431\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438.\n\n---\n\n## 6. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438\n\n\u041a\u0430\u0436\u0434\u044b\u0439 \u043f\u0443\u043d\u043a\u0442, \u043d\u0435 \u0438\u043c\u0435\u044e\u0449\u0438\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u043f\u043e\u0440\u044b \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 (\u0430 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 \u043f\u0443\u0441\u0442, \u00a70), \u043f\u043e\u043c\u0435\u0447\u0435\u043d \u043a\u0430\u043a **assumption** (\u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430/\u0432\u044b\u0431\u043e\u0440 \u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0449\u0438\u043a\u0430, \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430, \u043f\u043e\u0434\u043b\u0435\u0436\u0438\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0435 \u043d\u0430 \u044d\u0442\u0430\u043f\u0430\u0445 grounding/\u043f\u0438\u043b\u043e\u0442\u0430, \u043f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u043e\u0435 API).\n\n- **A1 (assumption, P1):** \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438 (\u00a73): \u0434\u0432\u0443\u0445\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0441 \u043b\u0438\u0434\u0435\u0440\u0430\u043c\u0438 20% (\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e, \u0432\u0430\u0440\u044c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 10/30%), \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0440\u043e\u043b\u0438; \u043d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u2014 \u043f\u043b\u043e\u0441\u043a\u0430\u044f, \u0431\u0435\u0437 \u043b\u0438\u0434\u0435\u0440\u043e\u0432; \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u0438\u043c\u0438\u0442\u0438\u0432\u044b \u0443 \u0430\u0433\u0435\u043d\u0442\u043e\u0432 \u043e\u0431\u043e\u0438\u0445 \u0442\u0438\u043f\u043e\u0432 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b.\n- **A2 (assumption, P2):** \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u0430\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u2014 \u0434\u0438\u0441\u043a\u0440\u0435\u0442\u043d\u043e\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u00ab\u0432\u0442\u043e\u0440\u0436\u0435\u043d\u0438\u0435\u00bb, \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u0435 \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u043d\u044b\u043c \u0441\u0447\u0451\u0442\u043e\u043c \u043f\u043e\u0440\u043e\u0433\u0430 T; \u043a \u043c\u043e\u043c\u0435\u043d\u0442\u0443 grounding \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f/\u0443\u0442\u043e\u0447\u043d\u044f\u0435\u0442\u0441\u044f \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u0430 (\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435 \u2014 \u0442\u043e\u0433\u0434\u0430 \u0441\u0435\u0440\u0438\u044f \u0441\u043e\u0431\u044b\u0442\u0438\u0439 \u0438 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0430\u044f time-varying \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430).\n- **A3 (assumption, P3):** \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u043f\u0440\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0434\u043e\u043b\u0438 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438 \u0438\u043b\u0438 \u0443\u0440\u043e\u043d); \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e API; \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f \u043b\u0435\u0442\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438 L (\u00a72.5).\n- **A4 (assumption, P4):** \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043c\u0438\u0440\u0430 (\u0440\u0430\u0437\u043c\u0435\u0440 \u043a\u0430\u0440\u0442\u044b, \u0440\u0435\u043b\u044c\u0435\u0444, \u0440\u0435\u0441\u0443\u0440\u0441\u044b, \u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u0437\u0438\u0446\u0438\u0438) \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043d\u0430 grounding/\u043f\u0438\u043b\u043e\u0442\u0435 \u043a\u0430\u043a \u0435\u0434\u0438\u043d\u0430\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0445 6 \u044f\u0447\u0435\u0435\u043a.\n- **A5 (assumption, P5):** \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u0430\u044f \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0438 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430 \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445.\n- **A6 (assumption, P6):** \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442 H \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440; \u043f\u043e\u0434\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435 \u0442\u0430\u043a, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u043b\u044f \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0431\u044b\u043b\u0430 \u0440\u0430\u0437\u0443\u043c\u043d\u043e\u0439 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, <30%); \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f assumption, \u0430 \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u043e\u0439 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u043e\u0439.\n- **A7 (assumption, P7):** \u043f\u043e\u0440\u043e\u0433 T \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440; \u043a\u0430\u043b\u0438\u0431\u0440\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435 (\u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0440\u0430\u043d\u043e \u0434\u043b\u044f \u0438\u0437\u043c\u0435\u0440\u0438\u043c\u043e\u0433\u043e \u044d\u0444\u0444\u0435\u043a\u0442\u0430, \u043d\u043e \u043d\u0435 \u043c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u043e), \u0437\u0430\u0442\u0435\u043c \u0432\u0430\u0440\u044c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 (T_low/T_high). \u0427\u0438\u0441\u043b\u0430 T \u2014 \u043d\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u043c\u044b\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b.\n- **A8 (assumption, P8):** \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f \u2014 pop(t) \u2264 1 (\u043b\u0438\u0431\u043e \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0439 \u043c\u0438\u043d\u0438\u043c\u0443\u043c \u043f\u043e \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u0435 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430); \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e \u043a\u043e \u0432\u0441\u0435\u043c \u044f\u0447\u0435\u0439\u043a\u0430\u043c; \u0435\u0441\u043b\u0438 API \u0437\u0430\u0434\u0430\u0451\u0442 \u0438\u043d\u043e\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u00ab\u043f\u0440\u043e\u0432\u0430\u043b\u0430 \u044d\u043f\u0438\u0437\u043e\u0434\u0430\u00bb, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u0435\u0434\u0438\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043d\u043e.\n- **A9 (assumption, P9):** \u0441\u0438\u0434-\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435 (\u00a74.3); \u0434\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u0444\u0430\u043a\u0442; \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0439 \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438 \u0432\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u0438 \u043e\u043d\u0430 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 power-\u0430\u043d\u0430\u043b\u0438\u0437\u0435.\n- **A10 (assumption, P10):** \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u043e\u0440\u043e\u0433\u0438: \u03b1 = 0.05 (\u0441 \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430\u043c\u0438 \u043d\u0430 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f), \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c 0.80, \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u0434\u0435\u0442\u0435\u043a\u0442\u0438\u0440\u0443\u0435\u043c\u044b\u0439 \u0440\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044f \u0434\u043e \u0430\u043d\u0430\u043b\u0438\u0437\u0430; N \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f power-\u0430\u043d\u0430\u043b\u0438\u0437\u043e\u043c, \u0434\u043e \u0435\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 R \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440.\n- **A11 (assumption, P11):** \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 \u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b; \u0431\u044e\u0434\u0436\u0435\u0442 \u044d\u0442\u0430\u043f\u043e\u0432 \u043e\u043f\u0438\u0441\u0430\u043d \u0432 \u00a77, \u0430 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0447\u0438\u0441\u043b\u0430 N \u0438 T \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043f\u0438\u043b\u043e\u0442\u0430.\n\n\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u043d\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u044e\u0442\u0441\u044f \u00ab\u0438\u0437 \u0433\u043e\u043b\u043e\u0432\u044b\u00bb, \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u0434\u0430\u043d\u043d\u044b\u0445 grounding/\u043f\u0438\u043b\u043e\u0442\u0430/\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f):\n- **U1:** \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043a\u043e\u0434\u0430/\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u2014 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 API, \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0435 \u0441\u043f\u043e\u0441\u043e\u0431\u044b \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f/\u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438, \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u0442\u0440\u0438\u0433\u0433\u0435\u0440\u043e\u0432, \u043a\u0440\u043e\u043c\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 \u043e\u0447\u043a\u043e\u0432.\n- **U2:** \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043b\u0438 \u0442\u0440\u0438\u0433\u0433\u0435\u0440 \u2014 \u043f\u043e\u0440\u043e\u0433 \u043e\u0447\u043a\u043e\u0432, \u0438\u043b\u0438 \u0443 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u0435\u0441\u0442\u044c \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0442\u0430\u0439\u043c\u0438\u043d\u0433\u0438/\u0443\u0441\u043b\u043e\u0432\u0438\u044f (\u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e time-varying \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u044b).\n- **U3:** \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c/\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0438 \u043f\u043e \u0441\u0438\u0434\u0443 (A9, \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f).\n- **U4:** \u043a\u0430\u043a \u0438\u043c\u0435\u043d\u043d\u043e \u00ab\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u00bb controlled-\u044f\u0447\u0435\u0439\u043a\u0443 \u043f\u0440\u0438 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f\u0445 (\u043f\u0440\u043e\u0434\u0443\u0431\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0441\u044e \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c t*_j, \u0438\u043b\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0435\u0440\u0432\u043e\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435) \u2014 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u0435 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u043d\u0430 grounding; \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 default \u2014 \u043f\u0440\u043e\u0434\u0443\u0431\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0441\u044e \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c.\n- **U5:** \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0433\u043e\u043d\u0430 (\u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 R, \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d T \u0438 \u043e\u0431\u044a\u0451\u043c \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438).\n- **U6:** \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c\u044b \u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 (L, \u0432\u0440\u0435\u043c\u044f \u0434\u043e \u043f\u043e\u0440\u043e\u0433\u0430) \u0434\u043b\u044f \u0434\u0430\u043d\u043d\u043e\u0433\u043e \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430.\n\n---\n\n## 7. \u042d\u0442\u0430\u043f\u044b \u0438 \u0431\u044e\u0434\u0436\u0435\u0442\n\n\u041d\u0438\u0436\u0435 \u2014 \u043f\u043b\u0430\u043d \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f; \u0446\u0438\u0444\u0440\u044b \u0432\u0440\u0435\u043c\u0435\u043d\u0438/\u0447\u0438\u0441\u043b\u0430 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u2014 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u044b-\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b, \u0443\u0442\u043e\u0447\u043d\u044f\u0435\u043c\u044b\u0435 \u043f\u043e \u0445\u043e\u0434\u0443; \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u041d\u0415 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0441\u044f.\n\n1. **\u042d\u0442\u0430\u043f 0 \u2014 Grounding (\u0434\u043e \u0437\u0430\u043c\u043e\u0440\u043e\u0437\u043a\u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438):** \u043d\u0430\u0439\u0442\u0438 \u0438 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u043a\u043e\u0434/\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044e \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430; \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c API: \u043e\u0431\u044a\u0435\u043a\u0442\u044b \u0430\u0433\u0435\u043d\u0442\u043e\u0432, \u0441\u043f\u043e\u0441\u043e\u0431 \u0437\u0430\u0434\u0430\u043d\u0438\u044f \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438 (\u0438\u043b\u0438 \u0435\u0433\u043e \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435), \u0441\u043f\u043e\u0441\u043e\u0431 \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f/\u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043e\u0447\u043a\u043e\u0432 \u0438 \u043f\u043e\u0440\u043e\u0433\u0430, \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u0443 \u00ab\u043f\u0440\u043e\u0432\u0430\u043b\u0430/\u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f\u00bb, \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u0438/\u0448\u0430\u0433\u043e\u0432, \u0441\u043f\u043e\u0441\u043e\u0431 \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0438 \u0441\u0438\u0434\u043e\u0432. \u0417\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c A1\u2013A8 \u043b\u0438\u0431\u043e \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c \u043d\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0438\u0437 API. \u0415\u0441\u043b\u0438 \u043a\u043e\u0434\u0430 \u043d\u0435\u0442 \u0432\u043e\u0432\u0441\u0435 \u2014 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0441\u0435 A1\u2013A8 \u043a\u0430\u043a \u044f\u0432\u043d\u044b\u0435 assumption \u0432 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0435.\n   *\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0432\u044b\u0445\u043e\u0434\u0430:* \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u0441 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430\u043c\u0438 \u0438 \u0441\u043f\u0438\u0441\u043a\u043e\u043c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u0445/\u043d\u0435\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u0445 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0439.\n2. **\u042d\u0442\u0430\u043f 1 \u2014 \u041f\u0438\u043b\u043e\u0442:** K = 10\u201320 \u0441\u0438\u0434\u043e\u0432 \u043d\u0430 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u044f\u0447\u0435\u0439\u043a\u0438 (\u043c\u0438\u043d\u0438\u043c\u0443\u043c (A_N, blocked), (A_N, enabled), (A_H, enabled) + \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0441\u0438\u0434-\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c\u0430 m=3 \u043f\u043e\u0432\u0442\u043e\u0440\u0430 \u043e\u0434\u043d\u043e\u0433\u043e \u0441\u0438\u0434\u0430, \u00a74.3). \u0412\u044b\u0445\u043e\u0434\u044b: \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u0438 D (\u043c\u0435\u0436\u0434\u0443- \u0438 \u0432\u043d\u0443\u0442\u0440\u0438-\u0441\u0438\u0434\u043e\u0432\u043e\u0439), \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0434\u043e\u043b\u044f \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043f\u0440\u0438 \u043f\u0440\u043e\u0431\u043d\u044b\u0445 H, time-to-threshold \u0438 t_trigger \u043f\u043e \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c, \u043b\u0435\u0442\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c L, \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0433\u043e\u043d\u0430 (\u0441\u0435\u043a\u0443\u043d\u0434\u044b/\u0448\u0430\u0433, \u043f\u0430\u043c\u044f\u0442\u044c), \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 T (\u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430: \u043d\u0435 \u043c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u043e \u0438 \u043d\u0435 \u043f\u043e\u0437\u0436\u0435 ~80% H).\n3. **\u042d\u0442\u0430\u043f 2 \u2014 Power-\u0430\u043d\u0430\u043b\u0438\u0437:** \u043f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u043f\u0438\u043b\u043e\u0442\u0430 \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u0435\u0442\u0441\u044f R (\u0447\u0438\u0441\u043b\u043e \u0441\u0438\u0434\u043e\u0432) \u0434\u043b\u044f \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u0438 \u0437\u0430\u0434\u0430\u043d\u043d\u043e\u0433\u043e \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u03b8_ctrl \u043f\u0440\u0438 \u03b1=0.05, \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 0.80 (\u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u044b\u0439 power \u043f\u043e paired-\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u0441 \u0443\u0447\u0451\u0442\u043e\u043c \u0432\u043d\u0443\u0442\u0440\u0438-\u0441\u0438\u0434\u043e\u0432\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u0438, \u0435\u0441\u043b\u0438 \u043e\u043d\u0430 \u0435\u0441\u0442\u044c). \u0412\u044b\u0445\u043e\u0434: \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0435 N=2\u00d7R\u00d73, \u043f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044c. R \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430.\n4. **\u042d\u0442\u0430\u043f 3 \u2014 \u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043f\u0440\u043e\u0433\u043e\u043d:** 2\u00d7R\u00d73 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u043f\u043e paired-seed \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0435 \u00a71.3, \u0441 \u043b\u043e\u0433\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u0440\u0438\u043a (\u00a72.7) \u0438 \u0432\u0435\u0440\u0441\u0438\u0438 \u043a\u043e\u0434\u0430.\n5. **\u042d\u0442\u0430\u043f 4 \u2014 \u0410\u043d\u0430\u043b\u0438\u0437 \u0438 \u043e\u0442\u0447\u0451\u0442:** \u00a75.1\u20135.3: \u0441\u0432\u043e\u0434\u043a\u0438, KM/log-rank, Cox \u0441 time-varying \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u043e\u0439 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u043e\u0439 PH, \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u044b \u03b8 \u0438 \u03b8_ctrl \u0441 \u0414\u0418, \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u043e T (\u0438 \u043f\u043e \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438, \u0435\u0441\u043b\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0431\u044e\u0434\u0436\u0435\u0442), \u043e\u0442\u0447\u0451\u0442 \u0441 \u044f\u0432\u043d\u043e\u0439 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u043e\u0439 \u043e\u0442\u0432\u0435\u0442\u0430 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 (\u00a75.2).\n\n\u0411\u044e\u0434\u0436\u0435\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0438: grounding ~1\u20132 \u0447\u0430\u0441\u0430 \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u043a\u043e\u0434\u0430 (\u0438\u043b\u0438 30 \u043c\u0438\u043d \u043f\u0440\u0438 \u0435\u0433\u043e \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u2014 \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u044f assumptions); \u043f\u0438\u043b\u043e\u0442 ~1 \u0447\u0430\u0441; power-\u0430\u043d\u0430\u043b\u0438\u0437 ~30\u201360 \u043c\u0438\u043d; \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043f\u0440\u043e\u0433\u043e\u043d \u2014 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a 2\u00d7R\u00d73 \u00d7 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0433\u043e\u043d\u0430 (\u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 U5); \u0430\u043d\u0430\u043b\u0438\u0437 ~1\u20132 \u0447\u0430\u0441\u0430. \u042d\u0442\u043e \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u044b, \u0430 \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u0435 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b.\n\n---\n\n## 8. \u0420\u0435\u0437\u044e\u043c\u0435 \u043e\u0442\u0432\u0435\u0442\u0430 \u043d\u0430 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 (\u0447\u0442\u043e \u043f\u043e\u043a\u0430\u0436\u0435\u0442 \u0434\u0438\u0437\u0430\u0439\u043d)\n\u0414\u0438\u0437\u0430\u0439\u043d \u0434\u0430\u0451\u0442 \u043e\u0442\u0432\u0435\u0442 \u0447\u0435\u0440\u0435\u0437 \u0442\u0440\u0438 \u0432\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0445 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u0430:\n- \u0394_A = enabled \u2212 blocked: \u043f\u043e\u043b\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 (\u0441\u043e\u0431\u044b\u0442\u0438\u0435+\u0442\u0430\u0439\u043c\u0438\u043d\u0433) \u043d\u0430 \u043a\u0430\u0436\u0434\u0443\u044e \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0443;\n- \u0394_A^ctrl = controlled \u2212 blocked: \u0447\u0438\u0441\u0442\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u044f (\u0431\u0435\u0437 \u0442\u0430\u0439\u043c\u0438\u043d\u0433-\u043a\u0430\u043d\u0430\u043b\u0430);\n- \u03b8 \u0438 \u03b8_ctrl (\u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 A\u00d7B): \u043c\u0435\u043d\u044f\u0435\u0442 \u043b\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0434\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0435\u0439 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f H vs N.\n\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043e \u00ab\u0432\u043b\u0438\u044f\u0435\u0442/\u043d\u0435 \u0432\u043b\u0438\u044f\u0435\u0442\u00bb \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f \u043f\u043e \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u0438 \u0438 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0435 \u03b8_ctrl (\u0438 \u0394^ctrl), \u0441 \u0443\u0447\u0451\u0442\u043e\u043c \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a \u0431\u0430\u043b\u0430\u043d\u0441\u0430 \u0442\u0435\u043c\u043f\u0430, \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f, PH \u0438 \u0441\u0438\u0434-\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c\u0430; \u0432\u0441\u0435 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043f\u043e\u0440\u043e\u0433\u0438 \u0438 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u2014 \u043d\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u043c\u044b\u0435 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b, \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 \u043a\u0430\u043a assumption (A1\u2013A11).", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f: (1) `ls -la /workspace` \u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u0430\u044f `find /workspace -type f` (\u043f\u043e\u0441\u043b\u0435 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u044f) \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b task.json; (2) `cat /workspace/task.json` \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 documents.track.md = \u00abDesign-only task; repositories and compute are not required.\u00bb; (3) `find / -maxdepth 3 -name 'track.md'` \u2014 \u0444\u0430\u0439\u043b\u0430 \u043d\u0435\u0442 \u0432\u043e \u0432\u0441\u0435\u0439 \u0424\u0421; (4) `python3 -V` = 3.14.4, \u0438\u043c\u043f\u043e\u0440\u0442 numpy/scipy/statsmodels/pandas \u0434\u0430\u0451\u0442 ModuleNotFoundError (\u043d\u0430\u0443\u0447\u043d\u044b\u0439 \u0441\u0442\u0435\u043a \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d). \u0412\u044b\u0432\u043e\u0434: \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e\u0439 \u0431\u0430\u0437\u044b \u043e\u0431 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0435 \u0430\u0433\u0435\u043d\u0442\u043e\u0432, \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0435, \u0442\u0440\u0438\u0433\u0433\u0435\u0440\u0430\u0445 \u0438 \u043c\u0435\u0442\u0440\u0438\u043a\u0435 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u043d\u0435\u0442; \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0432\u0441\u0435 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u0438\u043a\u0438 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 \u043a\u0430\u043a \u044f\u0432\u043d\u044b\u0435 assumption (A1\u2013A11), \u0442\u0440\u0435\u0431\u0443\u044e\u0449\u0438\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043d\u0430 \u044d\u0442\u0430\u043f\u0430\u0445 grounding \u0438 \u043f\u0438\u043b\u043e\u0442\u0430, \u0430 \u043d\u0435 \u043a\u0430\u043a \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0444\u0430\u043a\u0442\u044b. \u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0441\u044f; \u0432\u0441\u0435 \u0447\u0438\u0441\u043b\u0430 (K, R, N, H, T, \u0434\u043e\u043b\u0438 \u043b\u0438\u0434\u0435\u0440\u043e\u0432) \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u043c\u044b\u0435 \u043d\u0430 \u044d\u0442\u0430\u043f\u0430\u0445 0\u20132, \u0430 \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b.", "assumptions": ["A1: \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438 \u2014 \u0434\u0432\u0443\u0445\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0441 \u043b\u0438\u0434\u0435\u0440\u0430\u043c\u0438 (default 20%, \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c 10%/30%), \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0440\u043e\u043b\u0438; \u043d\u0435\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u2014 \u043f\u043b\u043e\u0441\u043a\u0430\u044f \u0431\u0435\u0437 \u043b\u0438\u0434\u0435\u0440\u043e\u0432; \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u0438\u043c\u0438\u0442\u0438\u0432\u044b \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b (\u00a73).", "A2: \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u2014 \u0434\u0438\u0441\u043a\u0440\u0435\u0442\u043d\u043e\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u00ab\u0432\u0442\u043e\u0440\u0436\u0435\u043d\u0438\u0435\u00bb, \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u0435 \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u0441\u0447\u0451\u0442\u043e\u043c \u043f\u043e\u0440\u043e\u0433\u0430 T; \u043f\u0440\u0438 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f\u0445 \u2014 \u0441\u0435\u0440\u0438\u044f \u0441\u043e\u0431\u044b\u0442\u0438\u0439 \u0438 time-varying \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430.", "A3: \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 \u043f\u0440\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0438 (\u043d\u0430\u043f\u0440., \u043f\u043e\u0442\u0435\u0440\u044f \u0434\u043e\u043b\u0438 \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438) \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e API; \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 \u043f\u0440\u0435\u0434\u0437\u0430\u0434\u0430\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f \u043b\u0435\u0442\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438 L.", "A4: \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043c\u0438\u0440\u0430 (\u043a\u0430\u0440\u0442\u0430, \u0440\u0435\u043b\u044c\u0435\u0444, \u0440\u0435\u0441\u0443\u0440\u0441\u044b, \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f) \u2014 \u0435\u0434\u0438\u043d\u0430\u044f \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0445 6 \u044f\u0447\u0435\u0435\u043a.", "A5: \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u0430\u044f \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u043f\u0443\u043b\u044f\u0446\u0438\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0438 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430 \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445.", "A6: \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442 H \u043f\u043e\u0434\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435 (\u0434\u043e\u043b\u044f \u0446\u0435\u043d\u0437\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 < ~30%) \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440, \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u0430\u044f \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0430.", "A7: \u043f\u043e\u0440\u043e\u0433 T \u043a\u0430\u043b\u0438\u0431\u0440\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435 (\u043d\u0435 \u043c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u043e, \u043d\u0435 \u043f\u043e\u0437\u0436\u0435 ~80% H) \u0438 \u0432\u0430\u0440\u044c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 T_low/T_high.", "A8: \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0432\u044b\u043c\u0438\u0440\u0430\u043d\u0438\u044f \u2014 pop(t) \u2264 1 \u043b\u0438\u0431\u043e \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0439 \u043c\u0438\u043d\u0438\u043c\u0443\u043c \u043f\u043e \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u0435 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430, \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e \u0432\u043e \u0432\u0441\u0435\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445.", "A9: \u0441\u0438\u0434-\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435 (m=3 \u043f\u043e\u0432\u0442\u043e\u0440\u0430 \u043e\u0434\u043d\u043e\u0433\u043e \u0441\u0438\u0434\u0430); \u0434\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435; \u043f\u0440\u0438 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0439 \u0441\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438 \u0432\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0441\u0442\u044c.", "A10: \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u043e\u0440\u043e\u0433\u0438 \u03b1=0.05 (\u0441 \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430\u043c\u0438), \u043c\u043e\u0449\u043d\u